code.cpp:
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    for (long long d = 2; d * d <= n; d++) {
        while (n % d == 0) {
            cout << d << " ";
            n /= d;
        }
    }
    if (n > 1) {
        cout << n << " ";
    }
    cout << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        for (long d = 2; d * d <= n; d++) {
            while (n % d == 0) {
                System.out.print(d + " ");
                n /= d;
            }
        }
        if (n > 1) {
            System.out.print(n + " ");
        }
        System.out.println();
    }
}
